package workflows

import (
	"context"
	"encoding/json"
	"testing"
	"time"

	"github.com/temporalio/benchmark-workers/activities"

	"github.com/stretchr/testify/mock"
	"github.com/stretchr/testify/require"
	"go.temporal.io/sdk/activity"
	"go.temporal.io/sdk/testsuite"
)

func TestDSLWorkflow(t *testing.T) {
	ts := &testsuite.WorkflowTestSuite{}
	env := ts.NewTestWorkflowEnvironment()

	env.RegisterActivityWithOptions(activities.EchoActivity, activity.RegisterOptions{Name: "Echo"})
	var echoCount int
	env.OnActivity("Echo", mock.Anything, mock.Anything).Return(func(ctx context.Context, input activities.EchoActivityInput) (string, error) {
		echoCount++
		return input.Message, nil
	})

	steps := []DSLStep{
		{Activity: "Echo", Input: map[string]interface{}{"Message": "test"}, Repeat: 3},
		{Child: []DSLStep{
			{Activity: "Echo", Input: map[string]interface{}{"Message": "test"}, Repeat: 3},
		}},
	}

	env.ExecuteWorkflow(DSLWorkflow, steps)

	require.True(t, env.IsWorkflowCompleted())
	require.NoError(t, env.GetWorkflowError())
	require.Equal(t, 6, echoCount, "Echo activity should be called 6 times")
}

func TestDSLWorkflowWithLocalActivity(t *testing.T) {
	ts := &testsuite.WorkflowTestSuite{}
	env := ts.NewTestWorkflowEnvironment()

	env.RegisterActivityWithOptions(activities.EchoActivity, activity.RegisterOptions{Name: "Echo"})
	var echoCount int
	var receivedInputs []activities.EchoActivityInput
	env.OnActivity("Echo", mock.Anything, mock.Anything).Return(func(ctx context.Context, input activities.EchoActivityInput) (string, error) {
		echoCount++
		receivedInputs = append(receivedInputs, input)
		return input.Message, nil
	})

	var localActivityCount int
	env.SetOnLocalActivityStartedListener(func(info *activity.Info, ctx context.Context, args []interface{}) {
		localActivityCount++
	})

	var steps []DSLStep
	require.NoError(t, json.Unmarshal([]byte(`[
		{"la":"Echo","i":{"Message":"test"},"r":3,"p":16}
	]`), &steps))

	env.ExecuteWorkflow(DSLWorkflow, steps)

	require.True(t, env.IsWorkflowCompleted())
	require.NoError(t, env.GetWorkflowError())
	require.Equal(t, 3, echoCount, "Echo activity should be called 3 times")
	require.Equal(t, 3, localActivityCount, "Echo activity should run as a local activity")
	for _, input := range receivedInputs {
		require.Equal(t, "test", input.Message)
		require.Len(t, input.Padding, 16)
	}
}

func TestDSLWorkflowWithTimerSleep(t *testing.T) {
	ts := &testsuite.WorkflowTestSuite{}
	env := ts.NewTestWorkflowEnvironment()

	env.RegisterActivityWithOptions(activities.EchoActivity, activity.RegisterOptions{Name: "Echo"})
	var echoCount int
	env.OnActivity("Echo", mock.Anything, mock.Anything).Return(func(ctx context.Context, input activities.EchoActivityInput) (string, error) {
		echoCount++
		return input.Message, nil
	})

	steps := []DSLStep{
		{SleepSeconds: 2, Repeat: 3},
		{Activity: "Echo", Input: map[string]interface{}{"Message": "test"}},
	}

	startTime := env.Now()
	env.ExecuteWorkflow(DSLWorkflow, steps)

	require.True(t, env.IsWorkflowCompleted())
	require.NoError(t, env.GetWorkflowError())
	require.Equal(t, 1, echoCount, "Echo activity should be called once")
	// The timer sleeps run via workflow.Sleep (durable timers) and are
	// fast-forwarded by the test env's time skipping: 3 repeats * 2s.
	require.Equal(t, 6*time.Second, env.Now().Sub(startTime))
}

func TestDSLWorkflowWithPadding(t *testing.T) {
	ts := &testsuite.WorkflowTestSuite{}
	env := ts.NewTestWorkflowEnvironment()

	env.RegisterActivityWithOptions(activities.EchoActivity, activity.RegisterOptions{Name: "Echo"})
	env.RegisterActivityWithOptions(activities.SleepActivity, activity.RegisterOptions{Name: "Sleep"})

	env.OnActivity("Echo", mock.Anything, mock.Anything).Return(func(ctx context.Context, input activities.EchoActivityInput) (string, error) {
		return input.Message, nil
	})

	env.OnActivity("Sleep", mock.Anything, mock.Anything).Return(func(ctx context.Context, input activities.SleepActivityInput) error {
		return nil
	})

	steps := []DSLStep{
		{
			Activity:    "Echo",
			Input:       map[string]interface{}{"Message": "test"},
			PaddingSize: 100, // 100 bytes of padding
		},
		{
			Activity:    "Sleep",
			Input:       map[string]interface{}{"SleepTimeInSeconds": 1},
			PaddingSize: 50, // 50 bytes of padding
		},
		{
			Activity: "Echo",
			Input:    map[string]interface{}{"Message": "no padding"},
			// No PaddingSize specified
		},
	}

	env.ExecuteWorkflow(DSLWorkflow, steps)

	require.True(t, env.IsWorkflowCompleted())
	require.NoError(t, env.GetWorkflowError())

	// The DSL workflow completed successfully - padding injection works at execution time
	// Individual padding verification is done in TestInjectPadding
}

func TestInjectPadding(t *testing.T) {
	// Test with map input (simulating JSON deserialization)
	echoInput := map[string]interface{}{"Message": "test"}
	injectPadding(echoInput, 100)

	// Should have padding added
	require.Contains(t, echoInput, "Padding", "Should have Padding field added")
	require.Len(t, echoInput["Padding"], 100, "Should have 100 bytes of padding")

	// Test with sleep activity input
	sleepInput := map[string]interface{}{"SleepTimeInSeconds": 5}
	injectPadding(sleepInput, 50)

	// Should have padding added
	require.Contains(t, sleepInput, "Padding", "Should have Padding field added")
	require.Len(t, sleepInput["Padding"], 50, "Should have 50 bytes of padding")

	// Test with zero padding
	echoInputNoPadding := map[string]interface{}{"Message": "no padding"}
	injectPadding(echoInputNoPadding, 0)

	// Should not have padding added
	require.NotContains(t, echoInputNoPadding, "Padding", "Should not have Padding field added")

	// Test with non-map input (should be unchanged - no panic)
	nonMap := "not a map"
	require.NotPanics(t, func() {
		injectPadding(nonMap, 100)
	}, "Should not panic with non-map input")
}

package main

import (
	"errors"
	"testing"
)

func TestInvocationMetricsContract(t *testing.T) {
	m := newInvocationMetrics()
	failure := errors.New("invocation failed")

	if err := m.run(true, func() error { return nil }); err != nil {
		t.Fatalf("waited success: %v", err)
	}
	if err := m.run(true, func() error { return failure }); !errors.Is(err, failure) {
		t.Fatalf("waited failure: got %v, want %v", err, failure)
	}
	if err := m.run(false, func() error { return nil }); err != nil {
		t.Fatalf("unwaited submission: %v", err)
	}
	if err := m.run(false, func() error { return failure }); !errors.Is(err, failure) {
		t.Fatalf("unwaited submission failure: got %v, want %v", err, failure)
	}

	families, err := m.registry.Gather()
	if err != nil {
		t.Fatal(err)
	}
	counters := map[string]float64{
		"benchmark_runner_invocations_started_total":   4,
		"benchmark_runner_invocations_completed_total": 1,
		"benchmark_runner_invocations_failed_total":    2,
	}
	histogramSeen := false
	for _, family := range families {
		if want, ok := counters[family.GetName()]; ok {
			if len(family.GetMetric()) != 1 || family.GetMetric()[0].GetCounter().GetValue() != want {
				t.Errorf("%s: got %v, want %v", family.GetName(), family.GetMetric(), want)
			}
			delete(counters, family.GetName())
		}
		if family.GetName() != "benchmark_runner_invocation_duration_seconds" {
			continue
		}
		histogramSeen = true
		counts := map[string]uint64{"completed": 1, "failed": 2}
		for _, metric := range family.GetMetric() {
			if len(metric.GetLabel()) != 1 || metric.GetLabel()[0].GetName() != "outcome" {
				t.Errorf("unexpected duration labels: %v", metric.GetLabel())
				continue
			}
			outcome := metric.GetLabel()[0].GetValue()
			want, ok := counts[outcome]
			if !ok {
				t.Errorf("unexpected outcome: %s", outcome)
				continue
			}
			histogram := metric.GetHistogram()
			if histogram.GetSampleCount() != want {
				t.Errorf("%s sample count: got %d, want %d", outcome, histogram.GetSampleCount(), want)
			}
			for _, bound := range []float64{0.005, 0.1, 1, 60, 600} {
				found := false
				for _, bucket := range histogram.GetBucket() {
					if bucket.GetUpperBound() == bound {
						found = true
						break
					}
				}
				if !found {
					t.Errorf("%s histogram missing bucket %g", outcome, bound)
				}
			}
			delete(counts, outcome)
		}
		if len(counts) != 0 {
			t.Errorf("missing duration outcomes: %v", counts)
		}
	}
	if len(counters) != 0 {
		t.Errorf("missing counters: %v", counters)
	}
	if !histogramSeen {
		t.Error("missing invocation duration histogram")
	}
}

