package activities

import (
	"context"
	"time"

	"go.temporal.io/sdk/activity"
)

type SleepActivityInput struct {
	SleepTimeInSeconds int
	Padding            []byte
}

func SleepActivity(ctx context.Context, input SleepActivityInput) error {
	sleepTimer := time.After(time.Duration(input.SleepTimeInSeconds) * time.Second)
	heartbeatTimeout := activity.GetInfo(ctx).HeartbeatTimeout

	// If no heartbeat timeout is set, we don't need heartbeating
	if heartbeatTimeout == 0 {
		for {
			select {
			case <-sleepTimer:
				return nil
			case <-ctx.Done():
				return ctx.Err()
			}
		}
	}

	// Create ticker only when heartbeating is needed
	heartbeatTick := time.Duration(0.8 * float64(heartbeatTimeout))
	ticker := time.NewTicker(heartbeatTick)
	defer ticker.Stop()

	for {
		select {
		case <-sleepTimer:
			return nil
		case <-ctx.Done():
			return ctx.Err()
		case <-ticker.C:
			activity.RecordHeartbeat(ctx)
		}
	}
}

type EchoActivityInput struct {
	Message string
	Padding []byte
}

func EchoActivity(ctx context.Context, input EchoActivityInput) (string, error) {
	return input.Message, nil
}

package workflows

import (
	"encoding/json"
	"fmt"
	"time"

	"github.com/temporalio/benchmark-workers/activities"

	"go.temporal.io/sdk/workflow"
)

type ExecuteActivityWorkflowInput struct {
	Count    int
	Activity string
	Input    interface{}
}

type ReceiveSignalWorkflowInput struct {
	Count int
	Name  string
}

// DSL step: an activity, a local activity, a child workflow (which is always
// this workflow), and/or a user timer.
type DSLStep struct {
	Activity      string      `json:"a,omitempty"`
	LocalActivity string      `json:"la,omitempty"`
	Input         interface{} `json:"i,omitempty"`
	Child         []DSLStep   `json:"c,omitempty"`
	Repeat        int         `json:"r,omitempty"`
	PaddingSize   int         `json:"p,omitempty"` // Size in bytes of padding to add to activity inputs
	SleepSeconds  int         `json:"t,omitempty"` // Seconds to sleep using workflow.Sleep
}

// injectPadding adds padding data to an activity input by adding a Padding field
func injectPadding(input interface{}, paddingSize int) {
	if paddingSize <= 0 {
		return
	}

	// Create padding data
	padding := make([]byte, paddingSize)
	for i := range padding {
		padding[i] = byte(i % 256) // Fill with repeating byte pattern
	}

	// If input is a map, add the Padding field directly
	if inputMap, ok := input.(map[string]interface{}); ok {
		inputMap["Padding"] = padding
	}
}

// localActivityInput converts the DSL's JSON-decoded input to the concrete
// types used by the activities registered by this worker. Unlike regular
// activities, local activity arguments do not pass through the data converter.
func localActivityInput(activityName string, input interface{}) (interface{}, error) {
	var target interface{}
	switch activityName {
	case "Echo":
		target = &activities.EchoActivityInput{}
	case "Sleep":
		target = &activities.SleepActivityInput{}
	default:
		return input, nil
	}

	data, err := json.Marshal(input)
	if err != nil {
		return nil, fmt.Errorf("encode %s local activity input: %w", activityName, err)
	}
	if err := json.Unmarshal(data, target); err != nil {
		return nil, fmt.Errorf("decode %s local activity input: %w", activityName, err)
	}

	switch value := target.(type) {
	case *activities.EchoActivityInput:
		return *value, nil
	case *activities.SleepActivityInput:
		return *value, nil
	default:
		panic("unreachable local activity input type")
	}
}

func ExecuteActivityWorkflow(ctx workflow.Context, input ExecuteActivityWorkflowInput) error {
	ao := workflow.ActivityOptions{
		StartToCloseTimeout: 1 * time.Minute,
	}
	ctx = workflow.WithActivityOptions(ctx, ao)

	for i := 0; i < input.Count; i++ {
		err := workflow.ExecuteActivity(ctx, input.Activity, input.Input).Get(ctx, nil)
		if err != nil {
			return err
		}
	}

	return nil
}

func ReceiveSignalWorkflow(ctx workflow.Context, input ReceiveSignalWorkflowInput) error {
	ch := workflow.GetSignalChannel(ctx, input.Name)

	for i := 0; i < input.Count; i++ {
		var data interface{}

		ch.Receive(ctx, &data)
	}

	return nil
}

// DSLWorkflow executes a list of DSLStep instructions.
func DSLWorkflow(ctx workflow.Context, steps []DSLStep) error {
	ao := workflow.ActivityOptions{
		StartToCloseTimeout: 1 * time.Minute,
	}
	ctx = workflow.WithActivityOptions(ctx, ao)
	lao := workflow.LocalActivityOptions{
		StartToCloseTimeout: 1 * time.Minute,
	}
	ctx = workflow.WithLocalActivityOptions(ctx, lao)

	for _, step := range steps {
		repeat := step.Repeat
		if repeat <= 0 {
			repeat = 1
		}
		for i := 0; i < repeat; i++ {
			if step.SleepSeconds > 0 {
				if err := workflow.Sleep(ctx, time.Duration(step.SleepSeconds)*time.Second); err != nil {
					return err
				}
			}
			if step.Activity != "" {
				// Inject padding into the activity input if specified
				injectPadding(step.Input, step.PaddingSize)
				if err := workflow.ExecuteActivity(ctx, step.Activity, step.Input).Get(ctx, nil); err != nil {
					return err
				}
			}
			if step.LocalActivity != "" {
				// Inject padding into the local activity input if specified
				injectPadding(step.Input, step.PaddingSize)
				input, err := localActivityInput(step.LocalActivity, step.Input)
				if err != nil {
					return err
				}
				if err := workflow.ExecuteLocalActivity(ctx, step.LocalActivity, input).Get(ctx, nil); err != nil {
					return err
				}
			}
			if len(step.Child) > 0 {
				if err := workflow.ExecuteChildWorkflow(ctx, DSLWorkflow, step.Child).Get(ctx, nil); err != nil {
					return err
				}
			}
		}
	}
	return nil
}

